package app.kinnect.live;
import android.Manifest;
import android.app.*;
import android.content.pm.PackageManager;
import android.os.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import org.webrtc.SurfaceViewRenderer;
/** Native room directory, broadcasting, playback and room chat. No WebView. */
public final class LiveActivity extends Activity implements NativeSocket.Events {
 private LinearLayout root,rooms,chat;private TextView status;private NativeSocket socket;private NativeRtc rtc;private JSONObject config;private boolean host,joined;private Button create;private android.media.AudioManager audio;private int previousMode;private boolean previousSpeaker;
 private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
 private LinearLayout column(){LinearLayout c=new LinearLayout(this);c.setOrientation(1);return c;}
 private TextView text(String s,int size){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(0xfff6f0ff);v.setPadding(dp(8),dp(8),dp(8),dp(8));return v;}
 private Button button(String name,Runnable click){Button b=new Button(this);b.setText(name);b.setAllCaps(false);b.setOnClickListener(v->click.run());return b;}
 public void onCreate(Bundle state){super.onCreate(state);root=column();root.setPadding(dp(16),0,dp(16),0);root.setBackgroundColor(0xff141329);root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(dp(16),i.getSystemWindowInsetTop(),dp(16),i.getSystemWindowInsetBottom());return i;});setContentView(root);root.addView(text("Kinnect · Trực tiếp",25));status=text("Đang kết nối…",14);root.addView(status);create=button("Bắt đầu phát trực tiếp",()->prepareHost());create.setEnabled(false);root.addView(create);ScrollView scroll=new ScrollView(this);rooms=column();scroll.addView(rooms);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));root.addView(button("Đóng",()->finish()));String origin=ServerConfig.resolve(getSharedPreferences("kinnect_settings",0).getString("server",null));NativeApi.shared.call("GET","/api/call-config",null,(data,error,code)->{if(isFinishing()||isDestroyed())return;if(error!=null){status.setText(error);return;}config=data;socket=new NativeSocket(origin,this);});audio=(android.media.AudioManager)getSystemService(AUDIO_SERVICE);previousMode=audio.getMode();previousSpeaker=audio.isSpeakerphoneOn();}
 private void prepareHost(){if(checkSelfPermission(Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED||checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.CAMERA,Manifest.permission.RECORD_AUDIO},301);return;}EditText title=new EditText(this);title.setHint("Chủ đề buổi trực tiếp");new Sheet(this).setTitle("Phát trực tiếp").setView(title).setPositiveButton("Bắt đầu",(d,w)->{host=true;socket.send(NativeSocket.json("type","create","title",title.getText().toString()));}).setNegativeButton("Hủy",null).show();}
 public void onRequestPermissionsResult(int code,String[] p,int[] grants){super.onRequestPermissionsResult(code,p,grants);if(code==301){if(grants.length==2&&grants[0]==0&&grants[1]==0)prepareHost();else status.setText("Cần quyền camera và micro để phát trực tiếp.");}}
 public void event(JSONObject m){String type=m.optString("type");if(type.equals("welcome")){status.setText("Chọn phòng để xem hoặc bắt đầu phát trực tiếp.");create.setEnabled(true);}if(type.equals("rooms")&&!joined){rooms.removeAllViews();JSONArray rows=m.optJSONArray("rooms");if(rows==null||rows.length()==0)rooms.addView(text("Chưa có ai đang trực tiếp.",17));for(int i=0;rows!=null&&i<rows.length();i++){JSONObject room=rows.optJSONObject(i);rooms.addView(button(room.optString("title")+"\n"+room.optString("host")+" · "+room.optInt("viewers")+" đang xem",()->{host=false;socket.send(NativeSocket.json("type","join","room",room.optString("id")));}));}}
 if(type.equals("joined")){joined=true;showRoom(m);}
 if(type.equals("peer")&&rtc!=null)rtc.offer(m.optString("id"));
 if(type.equals("signal")&&rtc!=null)rtc.signal(m.optString("from"),m);
 if(type.equals("peer-left")&&rtc!=null)rtc.remove(m.optString("id"));
 if(type.equals("count"))status.setText(m.optInt("viewers")+" người đang xem");
 if(type.equals("chat")&&chat!=null)chat.addView(text(m.optString("name")+": "+m.optString("text"),15));
 if(type.equals("room-ended")){Toast.makeText(this,"Buổi trực tiếp đã kết thúc.",Toast.LENGTH_LONG).show();finish();}
 if(type.equals("error"))status.setText(m.optString("message"));}
 private void showRoom(JSONObject m){root.removeAllViews();root.addView(text(m.optJSONObject("room").optString("title"),22));status=text("Đang kết nối media…",14);root.addView(status);SurfaceViewRenderer display=new SurfaceViewRenderer(this);root.addView(display,new LinearLayout.LayoutParams(-1,0,2));rtc=new NativeRtc(this,config,host?display:null,host?null:display,new NativeRtc.Events(){public void status(String s){status.setText(s);}public void signal(String peer,JSONObject payload){try{payload.put("type","signal");payload.put("to",peer);socket.send(payload);}catch(JSONException ignored){}}});audio.setMode(android.media.AudioManager.MODE_IN_COMMUNICATION);audio.setSpeakerphoneOn(true);if(host){try{rtc.media(this,true);status.setText("Đang phát trực tiếp");}catch(Exception e){status.setText("Không mở được camera/micro.");socket.send(NativeSocket.json("type","leave"));finish();return;}LinearLayout controls=new LinearLayout(this);final boolean[] mic={true},camera={true};controls.addView(button("Micro",()->{mic[0]=!mic[0];rtc.microphone(mic[0]);status.setText(mic[0]?"Micro đang bật":"Micro đã tắt");}),new LinearLayout.LayoutParams(0,-2,1));controls.addView(button("Camera",()->{camera[0]=!camera[0];rtc.camera(camera[0]);status.setText(camera[0]?"Camera đang bật":"Camera đã tắt");}),new LinearLayout.LayoutParams(0,-2,1));controls.addView(button("Đổi camera",()->rtc.flip()),new LinearLayout.LayoutParams(0,-2,1));controls.addView(button("✨ Hiệu ứng",()->effectsMenu()),new LinearLayout.LayoutParams(0,-2,1));root.addView(controls);}ScrollView sc=new ScrollView(this);chat=column();sc.addView(chat);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));LinearLayout composer=new LinearLayout(this);EditText input=new EditText(this);input.setHint("Viết bình luận…");input.setTextColor(0xfff6f0ff);input.setHintTextColor(0xffb9adc9);composer.addView(input,new LinearLayout.LayoutParams(0,-2,1));composer.addView(button("Gửi",()->{String value=input.getText().toString().trim();if(value.isEmpty())return;socket.send(NativeSocket.json("type","chat","text",value));input.setText("");}));root.addView(composer);root.addView(button(host?"Kết thúc trực tiếp":"Rời phòng",()->finish()));}
 public void closed(){if(isFinishing())return;status.setText("Đã mất kết nối. Hãy mở lại mục Trực tiếp.");create.setEnabled(false);if(rtc!=null){rtc.close();rtc=null;}}
 protected void onStop(){super.onStop();if(joined)finish();}
 protected void onDestroy(){if(socket!=null)socket.close();if(rtc!=null)rtc.close();if(audio!=null){audio.setMode(previousMode);audio.setSpeakerphoneOn(previousSpeaker);}super.onDestroy();}
 private void effectsMenu(){final LiveEffects fx=rtc==null?null:rtc.effects();if(fx==null)return;String[] items=new String[LiveEffects.FILTERS.length+LiveEffects.STICKERS.length];int k=0;for(String[] f:LiveEffects.FILTERS)items[k++]=(fx.filter.equals(f[0])?"✓ ":"")+"Bộ lọc: "+f[1];for(String[] s:LiveEffects.STICKERS)items[k++]=(fx.sticker.equals(s[0])?"✓ ":"")+(s[2].isEmpty()?"":s[2]+" ")+s[1];new Sheet(this).setTitle("Hiệu ứng live").setItems(items,(d,w)->{if(w<LiveEffects.FILTERS.length)fx.filter=LiveEffects.FILTERS[w][0];else fx.sticker=LiveEffects.STICKERS[w-LiveEffects.FILTERS.length][0];status.setText(fx.sticker.equals("none")?"Đã áp dụng hiệu ứng":"Đưa khuôn mặt vào khung hình");}).show();}
}
